CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TEXT NOT NULL,created_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS students (id INTEGER PRIMARY KEY AUTOINCREMENT,student_id TEXT NOT NULL UNIQUE,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,department TEXT NOT NULL,password_hash TEXT NOT NULL,qr_identifier TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS equipment (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT NOT NULL,qr_code TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'AVAILABLE',condition TEXT NOT NULL DEFAULT 'GOOD',location TEXT,notes TEXT,added_at TEXT NOT NULL,added_by INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS slots (id INTEGER PRIMARY KEY AUTOINCREMENT,equipment_id INTEGER NOT NULL REFERENCES equipment(id),date TEXT NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),available_count INTEGER NOT NULL CHECK(available_count>=0),booking_cutoff_at TEXT NOT NULL,allocation_run_at TEXT,status TEXT NOT NULL DEFAULT 'OPEN',created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bookings (id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL REFERENCES students(id),equipment_id INTEGER NOT NULL REFERENCES equipment(id),slot_id INTEGER NOT NULL REFERENCES slots(id),status TEXT NOT NULL DEFAULT 'REQUESTED',priority_score REAL,queue_position INTEGER,created_at TEXT NOT NULL,allocated_at TEXT,UNIQUE(student_id,slot_id));
CREATE TABLE IF NOT EXISTS transactions (id INTEGER PRIMARY KEY AUTOINCREMENT,booking_id INTEGER REFERENCES bookings(id),student_id INTEGER NOT NULL REFERENCES students(id),equipment_id INTEGER NOT NULL REFERENCES equipment(id),issued_at TEXT NOT NULL,due_at TEXT NOT NULL,returned_at TEXT,status TEXT NOT NULL DEFAULT 'ISSUED',condition_on_return TEXT,damage_report TEXT,issued_by INTEGER NOT NULL REFERENCES users(id),returned_to INTEGER REFERENCES users(id));
CREATE UNIQUE INDEX IF NOT EXISTS java_one_open_issue ON transactions(equipment_id) WHERE status IN ('ISSUED','OVERDUE');
CREATE UNIQUE INDEX IF NOT EXISTS java_one_issue_per_booking ON transactions(booking_id) WHERE booking_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS usage_statistics (id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL UNIQUE REFERENCES students(id),sessions_last_7_days INTEGER NOT NULL DEFAULT 0,last_session_at TEXT,total_sessions INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fairness_config (id INTEGER PRIMARY KEY CHECK(id=1),daily_usage_cap INTEGER NOT NULL DEFAULT 2,recency_threshold_days INTEGER NOT NULL DEFAULT 2,recency_weight REAL NOT NULL DEFAULT 0.5,updated_at TEXT NOT NULL,updated_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL REFERENCES students(id),type TEXT NOT NULL,title TEXT NOT NULL,message TEXT NOT NULL,is_read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,expires_at TEXT);
CREATE TABLE IF NOT EXISTS defaulters (id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL REFERENCES students(id),transaction_id INTEGER NOT NULL UNIQUE REFERENCES transactions(id),detected_at TEXT NOT NULL,overdue_days INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',resolved_at TEXT,resolved_by INTEGER REFERENCES users(id));
CREATE INDEX IF NOT EXISTS java_bookings_slot ON bookings(slot_id,status);
CREATE INDEX IF NOT EXISTS java_transactions_student ON transactions(student_id,status);
INSERT OR IGNORE INTO fairness_config(id,updated_at) VALUES(1,strftime('%Y-%m-%dT%H:%M:%SZ','now'));
